result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

result = Drugs.CALCULATE(
