average_ddd_per_drug = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(PRESENT(end_dt)).CALCULATE(
            treatment_duration_days=DATEDIFF("days", start_dt, end_dt)
        ).WHERE(
            treatment_duration_days > 0
        ).CALCULATE(
            ddd_value=tot_drug_amt / treatment_duration_days
        ).ddd_value
    )
)

